async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8", { fatal: true });
  let accepted = 0;
  let rejected = 0;
  let line = 1;
  let pending = "";
  let shouldCancel = true;

  async function visitLine(source) {
    if (/^\s*$/u.test(source)) return false;

    let value;
    try {
      value = JSON.parse(source);
    } catch {
      rejected++;
      return false;
    }

    accepted++;
    return (await visitor({ line, value })) === false;
  }

  async function consume(text) {
    pending += text;

    for (;;) {
      const newline = pending.indexOf("\n");
      if (newline === -1) return false;

      const source = pending.slice(0, newline);
      pending = pending.slice(newline + 1);

      if (await visitLine(source)) return true;
      line++;
    }
  }

  try {
    for (;;) {
      const { done, value } = await reader.read();

      if (!done) {
        if (await consume(decoder.decode(value, { stream: true }))) {
          return { accepted, rejected, stopped: true };
        }
        continue;
      }

      if (await consume(decoder.decode())) {
        shouldCancel = false;
        return { accepted, rejected, stopped: true };
      }

      if (pending !== "" && await visitLine(pending)) {
        shouldCancel = false;
        return { accepted, rejected, stopped: true };
      }

      shouldCancel = false;
      return { accepted, rejected, stopped: false };
    }
  } finally {
    if (shouldCancel) {
      await reader.cancel();
    }
    reader.releaseLock();
  }
}
